<template><div><div class="page-head"><div><h1>Expenses</h1><p>Track operating costs and business cash outflows.</p></div><button class="btn btn-primary" @click="openCreate">+ Record expense</button></div><div class="grid grid-cols-1 gap-3 sm:grid-cols-3 mb-4"><div class="card metric"><div class="metric-label">This month</div><div class="metric-value mt-2">{{money(total)}}</div><div class="metric-trend mt-3">Recorded expenses</div></div><div class="card metric"><div class="metric-label">Transactions</div><div class="metric-value mt-2">{{expenses.length}}</div><div class="metric-trend mt-3">Current page</div></div><div class="card metric"><div class="metric-label">Average</div><div class="metric-value mt-2">{{money(expenses.length?total/expenses.length:0)}}</div><div class="metric-trend mt-3">Per transaction</div></div></div><div class="card mb-4 p-4"><input v-model="search" @keyup.enter="load" class="input md:max-w-sm" placeholder="Search expense number or description…"></div><div class="card table-wrap"><table class="data-table"><thead><tr><th>Expense</th><th>Date</th><th>Description</th><th>Category</th><th>Method</th><th>Amount</th><th class="text-right">Actions</th></tr></thead><tbody><tr v-for="e in expenses" :key="e.id"><td>{{e.expense_number}}</td><td>{{formatDisplayDate(e.expense_date)}}</td><td>{{e.description}}</td><td>{{e.category?.name||'—'}}</td><td class="capitalize">{{e.payment_method}}</td><td>{{money(e.amount)}}</td><td><div class="flex justify-end gap-2"><button class="btn btn-soft" @click="edit(e)">Edit</button><button class="btn btn-danger" @click="remove(e)">Delete</button></div></td></tr><tr v-if="!expenses.length"><td colspan="7"><div class="empty">No expenses recorded.</div></td></tr></tbody></table></div><AppModal :open="open" :title="editing?'Edit expense':'Record expense'" @close="open=false"><form @submit.prevent="save" class="grid grid-cols-1 gap-4 md:grid-cols-2"><div><label class="label">Date *</label><input v-model="form.expense_date" class="input" type="date" required></div><div><label class="label">Amount *</label><MoneyInput v-model="form.amount" :min="0.01" /></div><div class="md:col-span-2"><label class="label">Description *</label><input v-model="form.description" class="input" required></div><div><label class="label">Category</label><select v-model="form.category_id" class="input"><option :value="null">Uncategorised</option><option v-for="c in categories" :key="c.id" :value="c.id">{{c.name}}</option></select></div><div><label class="label">Payment method</label><select v-model="form.payment_method" class="input"><option>cash</option><option>bank</option><option>mobile_money</option><option>card</option><option>cheque</option></select></div><div class="md:col-span-2 flex justify-end gap-2 border-t border-slate-100 pt-4"><button type="button" class="btn btn-soft" @click="open=false">Cancel</button><button class="btn btn-primary">{{saving?'Saving…':'Save expense'}}</button></div></form></AppModal><div v-if="error" class="fixed bottom-5 right-5 rounded-xl bg-rose-600 px-4 py-3 text-xs font-bold text-white shadow-xl">{{error}}</div></div></template>
<script setup lang="ts">import MoneyInput from '../../components/MoneyInput.vue';import {formatDate as formatDisplayDate} from '../../utils/date';import {computed,onMounted,ref} from 'vue';import {api,apiError} from '../../services/api';import {useConfirm} from '../../stores/confirm';import {useToast} from '../../stores/toast';import AppModal from '../../components/AppModal.vue';const {ask:confirm}=useConfirm();const toast=useToast();const expenses=ref<any[]>([]),categories=ref<any[]>([]),search=ref(''),open=ref(false),editing=ref<any>(null),saving=ref(false),error=ref('');const blank=()=>({expense_date:new Date().toISOString().slice(0,10),description:'',amount:0,category_id:null,payment_method:'cash'});const form=ref<any>(blank());const total=computed(()=>expenses.value.reduce((s,e)=>s+Number(e.amount||0),0));function money(v:any){return new Intl.NumberFormat('en-TZ',{style:'currency',currency:'TZS',maximumFractionDigits:0}).format(Number(v||0))}async function load(){const [e,c]=await Promise.all([api.get('/expenses',{params:{search:search.value,per_page:50}}),api.get('/expense-categories')]);expenses.value=e.data.data;categories.value=c.data}function openCreate(){editing.value=null;form.value=blank();open.value=true}function edit(e:any){editing.value=e;form.value={...blank(),...e};open.value=true}async function save(){saving.value=true;error.value='';try{if(editing.value)await api.put(`/expenses/${editing.value.id}`,form.value);else await api.post('/expenses',form.value);open.value=false;await load();toast.success(editing.value?'Expense updated':'Expense recorded', editing.value?'Changes saved successfully.':'Expense was recorded successfully.')}catch(e){error.value=apiError(e);toast.error('Action failed', apiError(e))}finally{saving.value=false}}async function remove(e:any){if(!(await confirm({title:'Delete expense?',message:`You are about to delete ${e.expense_number}. This action cannot be undone.`,confirmText:'Delete',danger:true})))return;try{await api.delete(`/expenses/${e.id}`);await load();toast.success('Expense deleted', `${e.expense_number} was deleted successfully.`)}catch(err){error.value=apiError(err);toast.error('Action failed', apiError(err))}}onMounted(load)</script>
